created=[];appended=[]
for slug,name,meas,metric,opn,small,srcs,desc in EVALS:
    p=os.path.join(E,slug+".md")
    if os.path.exists(p):
        txt=open(p,encoding="utf-8").read()
        if "Gemini 4 Argon" not in txt:
            with open(p,"a",encoding="utf-8") as f: f.write("\n"+USED+"\n")
        appended.append(slug); continue
    body=f"""# {name}

- Slug: {slug}
- What it measures: {meas}
- Metric: {metric}
- Open-source: {opn}
- Runnable on a 0.5B-7B open model: {small}
- Source URL(s): {' ; '.join(srcs)}
- Fetched: 2026-10-19

## Description
{desc}

## Used by
{USED}
"""
    open(p,"w",encoding="utf-8").write(body); created.append(slug)
print("created",len(created),created); print("appended",len(appended),appended)
